import numpy as np
from scipy.linalg import sqrtm
rng=np.random.default_rng(1)
for j in range(10000):
 X=rng.normal(size=(2,2));Y=rng.normal(size=(2,2))
 A=X.T@X;B=Y.T@Y
 Z=sqrtm(A)+sqrtm(B)-sqrtm(A+B)
 if np.linalg.eigvalsh(Z).min()<-1e-7:
  print('Square-root subadditivity fails in operator order:',np.linalg.eigvalsh(Z));break
else:print('none')

